require dirname(__DIR__) . '/includes/bootstrap.php'; $user=require_role('student'); $title='Your student space'; require ROOT . '/includes/dashboard-start.php';
?>
<div class="welcome-card" data-reveal="fade"><div><h2>Welcome back, <?= e(explode(' ',$user['name'])[0]) ?>.</h2><p>Your next chapter, a little more organized.</p></div><a class="btn btn-light" href="<?= url('browse.php') ?>">Find a place <i class="bi bi-arrow-right" aria-hidden="true"></i></a></div>
<div class="stats-grid"><?php foreach ([['Saved places','SELECT COUNT(*) FROM favorites WHERE user_id=?','bi-heart'],['Unlocked places','SELECT COUNT(*) FROM unlocked_listings WHERE user_id=?','bi-unlock'],['Simulated transactions','SELECT COUNT(*) FROM unlock_transactions WHERE user_id=?','bi-receipt']] as [$label,$sql,$icon]) stat_card($label,(int)scalar($sql,[$user['id']]),$icon); ?></div>
<div class="panel" data-reveal><h3>Account information</h3><p class="mb-2"><strong><?= e($user['name']) ?></strong><br><?= e($user['email']) ?><?= $user['phone'] !== '' ? '<br>' . e($user['phone']) : '' ?></p><a class="btn btn-outline-primary btn-sm" href="<?= url('student/profile.php') ?>">Edit profile</a></div>
<h2 class="section-title">Recently explored</h2><?php $recent=rows(listing_select() . ' JOIN recent_views rv ON rv.dormitory_id=d.id WHERE rv.user_id=? AND ' . public_condition() . ' ORDER BY rv.viewed_at DESC LIMIT 3',[$user['id']]); ?><?php if ($recent): ?><div class="cards-grid dashboard-cards"><?php listing_cards($recent); ?></div><?php else: ?><div class="empty-state"><i class="bi bi-compass" aria-hidden="true"></i><h2>Nothing viewed yet.</h2><p>Your recently viewed places will appear here.</p><a class="btn btn-primary" href="<?= url('browse.php') ?>">Find your first favorite</a></div><?php endif; ?><h2 class="section-title">Simulated transaction history</h2><?php $total=(int)scalar('SELECT COUNT(*) FROM unlock_transactions WHERE user_id=?',[$user['id']]); $transactions=rows('SELECT t.*,d.name dormitory FROM unlock_transactions t JOIN dormitories d ON d.id=t.dormitory_id WHERE t.user_id=? ORDER BY t.id DESC LIMIT 10 OFFSET ' . ((page_number()-1)*10),[$user['id']]); require ROOT . '/includes/transaction-table.php'; paginate($total,10); require ROOT . '/includes/dashboard-end.php'; ?>
